package com.ruoyi.web.biz;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.jdbc.core.JdbcTemplate;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.framework.web.service.PermissionService;
@Service
public class CompanyOnboardingService {
 private final JdbcTemplate db; private final BizMapper scope; private final PermissionService permissions;
 public CompanyOnboardingService(CompanyOnboardingMapper mapper,BizMapper scope,PermissionService p){this.db=mapper.database();this.scope=scope;this.permissions=p;}
 private long uid(){return SecurityUtils.getUserId();}
 private void perm(String p){if(!permissions.hasPermi("biz:onboarding:"+p))throw new AccessDeniedException("没有操作权限");}
 private void platform(){perm("review");if(!scope.platform(uid()))throw new AccessDeniedException("仅平台管理员可审核");}
 private void lockUser(long id){if(db.queryForList("SELECT user_id FROM sys_user WHERE user_id=? AND status='0' AND del_flag='0' FOR UPDATE",id).isEmpty())throw new ServiceException("申请账号已停用或不存在",409);}
 private Map<String,Object> row(long id,boolean lock){List<Map<String,Object>> rows=db.queryForList("SELECT * FROM biz_company_apply WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw new ServiceException("申请不存在",404);Map<String,Object> a=rows.get(0);if(((Number)a.get("applicant_id")).longValue()!=uid()&&!scope.platform(uid()))throw new AccessDeniedException("无权访问该申请");return a;}
 public Map<String,Object> list(boolean review){if(review)platform();else perm("apply");return Map.of("rows",review?db.queryForList("SELECT * FROM biz_company_apply ORDER BY id DESC LIMIT 200"):db.queryForList("SELECT * FROM biz_company_apply WHERE applicant_id=? ORDER BY id DESC LIMIT 200",uid()));}
 public Map<String,Object> detail(long id){Map<String,Object> a=row(id,false);a.put("audits",db.queryForList("SELECT id,round_no,from_status,to_status,opinion,reviewer_id,reviewed_at FROM biz_audit_record WHERE business_type='company_apply' AND business_id=? ORDER BY round_no",id));return a;}
 private void text(String s,int max,String name){if(s==null||s.isBlank()||s.length()>max)throw new ServiceException(name+"必填或长度无效",400);}
 private void valid(CompanyApplication a){text(a.companyName(),100,"企业名称");text(a.contactName(),50,"负责人");text(a.address(),255,"地址");if(a.contactPhone()==null||!a.contactPhone().matches("[0-9+() -]{6,30}"))throw new ServiceException("联系电话无效",400);if(a.introduction()!=null&&a.introduction().length()>2000)throw new ServiceException("简介过长",400);
 String chars="0123456789ABCDEFGHJKLMNPQRTUWXY";int[] weights={1,3,9,27,19,26,16,17,20,29,25,13,8,24,10,30,28};String code=a.creditCode();if(code==null||code.length()!=18)throw new ServiceException("信用代码必须18位",400);int sum=0;for(int i=0;i<17;i++){int n=chars.indexOf(code.charAt(i));if(n<0)throw new ServiceException("信用代码字符无效",400);sum+=n*weights[i];}if(chars.charAt((31-sum%31)%31)!=code.charAt(17))throw new ServiceException("信用代码校验位无效",400);
 if(a.licenseId()==null||db.queryForObject("SELECT COUNT(*) FROM biz_company_license WHERE id=? AND owner_id=?",Long.class,a.licenseId(),uid())!=1)throw new ServiceException("请上传本人营业执照",400);
 }
 @Transactional public long save(Long id,CompanyApplication a){perm("apply");valid(a);lockUser(uid());if(scope.company(uid())!=null)throw new ServiceException("账号已归属企业，不能重复入驻",409);if(db.queryForObject("SELECT COUNT(*) FROM biz_company WHERE credit_code=?",Long.class,a.creditCode())>0)throw new ServiceException("企业已入驻",409);
 if(id==null){if(db.queryForObject("SELECT COUNT(*) FROM biz_company_apply WHERE credit_code=? OR (applicant_id=? AND status IN ('DRAFT','PENDING'))",Long.class,a.creditCode(),uid())>0)throw new ServiceException("存在重复申请，请修改原申请",409);db.update("INSERT INTO biz_company_apply(applicant_id,company_name,credit_code,contact_name,contact_phone,address,introduction,qualification_ref,status,create_by) VALUES(?,?,?,?,?,?,?,?,'DRAFT',?)",uid(),a.companyName(),a.creditCode(),a.contactName(),a.contactPhone(),a.address(),a.introduction()==null?"":a.introduction(),a.licenseId().toString(),SecurityUtils.getUsername());return db.queryForObject("SELECT id FROM biz_company_apply WHERE applicant_id=? AND status='DRAFT'",Long.class,uid());}
 Map<String,Object> old=row(id,true);if(((Number)old.get("applicant_id")).longValue()!=uid())throw new AccessDeniedException("仅申请人可修改");if(!Set.of("DRAFT","REJECTED").contains(old.get("status")))throw new ServiceException("当前状态不可修改",409);
 if(db.queryForObject("SELECT COUNT(*) FROM biz_company_apply WHERE credit_code=? AND id<>?",Long.class,a.creditCode(),id)>0)throw new ServiceException("信用代码重复申请",409);
 if(a.version()==null||db.update("UPDATE biz_company_apply SET company_name=?,credit_code=?,contact_name=?,contact_phone=?,address=?,introduction=?,qualification_ref=?,version=version+1,update_by=? WHERE id=? AND version=?",a.companyName(),a.creditCode(),a.contactName(),a.contactPhone(),a.address(),a.introduction()==null?"":a.introduction(),a.licenseId().toString(),SecurityUtils.getUsername(),id,a.version())!=1)throw new ServiceException("版本冲突，请刷新",409);return id;}
 @Transactional public void submit(long id){perm("apply");Map<String,Object> a=row(id,true);if(((Number)a.get("applicant_id")).longValue()!=uid())throw new AccessDeniedException("仅申请人可提交");if(!Set.of("DRAFT","REJECTED").contains(a.get("status")))throw new ServiceException("当前状态不可提交",409);lockUser(uid());if(scope.company(uid())!=null)throw new ServiceException("账号已归属企业",409);
 db.update("UPDATE biz_company_apply SET round_no=round_no+IF(status='REJECTED',1,0),status='PENDING',version=version+1,update_by=? WHERE id=?",SecurityUtils.getUsername(),id);
 }
 @Transactional public void review(long id,boolean approve,String opinion){platform();text(opinion,500,"审核意见");Map<String,Object> a=row(id,true);long applicant=((Number)a.get("applicant_id")).longValue();if(applicant==uid())throw new AccessDeniedException("不能审核本人申请");if(!"PENDING".equals(a.get("status")))throw new ServiceException("申请不在待审核状态",409);lockUser(applicant);Long company=null;
 if(approve){if(scope.company(applicant)!=null||db.queryForObject("SELECT COUNT(*) FROM biz_company_user WHERE user_id=? AND status='ACTIVE'",Long.class,applicant)>0)throw new ServiceException("申请人已归属企业",409);db.update("INSERT INTO biz_company(company_name,credit_code,contact_name,contact_phone,address,introduction,status,create_by) VALUES(?,?,?,?,?,?,'ACTIVE',?)",a.get("company_name"),a.get("credit_code"),a.get("contact_name"),a.get("contact_phone"),a.get("address"),a.get("introduction"),SecurityUtils.getUsername());company=db.queryForObject("SELECT id FROM biz_company WHERE credit_code=?",Long.class,a.get("credit_code"));db.update("INSERT INTO biz_company_user(company_id,user_id,status) VALUES(?,?,'ACTIVE')",company,applicant);db.update("INSERT INTO biz_employee_info(company_id,user_id,employee_no,real_name,status) VALUES(?,?,?,?,'ACTIVE')",company,applicant,"ADMIN-"+applicant,a.get("contact_name"));db.update("INSERT IGNORE INTO sys_user_role(user_id,role_id) SELECT ?,role_id FROM sys_role WHERE role_key='company_admin' AND status='0' AND del_flag='0'",applicant);if(db.queryForObject("SELECT COUNT(*) FROM sys_user_role ur JOIN sys_role r ON ur.role_id=r.role_id WHERE ur.user_id=? AND r.role_key='company_admin' AND r.status='0'",Long.class,applicant)!=1)throw new ServiceException("企业管理员角色配置异常",409);}
 String status=approve?"APPROVED":"REJECTED";db.update("UPDATE biz_company_apply SET status=?,company_id=?,version=version+1,update_by=? WHERE id=?",status,company,SecurityUtils.getUsername(),id);db.update("INSERT INTO biz_audit_record(company_id,business_type,business_id,round_no,applicant_id,reviewer_id,from_status,to_status,opinion,status) VALUES(?,'company_apply',?,?,?,?, 'PENDING',?,?,'RECORDED')",company,id,a.get("round_no"),applicant,uid(),status,opinion);
 }
 public List<Map<String,Object>> companies(){perm("manage");if(scope.platform(uid()))return db.queryForList("SELECT * FROM biz_company ORDER BY id DESC LIMIT 200");Long own=scope.company(uid());if(own==null)throw new AccessDeniedException("无企业归属");return db.queryForList("SELECT * FROM biz_company WHERE id=?",own);}
 @Transactional public void updateCompany(long id,CompanyApplication a){perm("manage");Long own=scope.company(uid());if(!scope.platform(uid())&&(own==null||own!=id))throw new AccessDeniedException("不能管理其他企业");text(a.companyName(),100,"企业名称");text(a.contactName(),50,"负责人");text(a.address(),255,"地址");if(a.contactPhone()==null||!a.contactPhone().matches("[0-9+() -]{6,30}")||a.introduction()!=null&&a.introduction().length()>2000)throw new ServiceException("电话或简介无效",400);if(a.version()==null||db.update("UPDATE biz_company SET company_name=?,contact_name=?,contact_phone=?,address=?,introduction=?,version=version+1,update_by=? WHERE id=? AND version=?",a.companyName(),a.contactName(),a.contactPhone(),a.address(),a.introduction()==null?"":a.introduction(),SecurityUtils.getUsername(),id,a.version())!=1)throw new ServiceException("企业不存在或版本已变更",409);}
 public long license(byte[] data,String type){perm("apply");if(data.length==0||data.length>5*1024*1024)throw new ServiceException("文件须为1字节至5MB",400);boolean pdf=data.length>4&&new String(Arrays.copyOf(data,5),java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-");boolean png=data.length>8&&data[0]==(byte)137&&data[1]==80&&data[2]==78&&data[3]==71;boolean jpg=data.length>3&&data[0]==(byte)255&&data[1]==(byte)216&&data[2]==(byte)255;if(!(pdf&&"application/pdf".equals(type)||png&&"image/png".equals(type)||jpg&&"image/jpeg".equals(type)))throw new ServiceException("仅支持PDF/PNG/JPEG营业执照",400);org.springframework.jdbc.support.GeneratedKeyHolder key=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{var p=c.prepareStatement("INSERT INTO biz_company_license(owner_id,content_type,file_data) VALUES(?,?,?)",java.sql.Statement.RETURN_GENERATED_KEYS);p.setLong(1,uid());p.setString(2,type);p.setBytes(3,data);return p;},key);return key.getKey().longValue();}
 public Map<String,Object> download(long id){List<Map<String,Object>> files=db.queryForList("SELECT * FROM biz_company_license WHERE id=?",id);if(files.isEmpty())throw new ServiceException("文件不存在",404);Map<String,Object> file=files.get(0);if(((Number)file.get("owner_id")).longValue()!=uid()&&!scope.platform(uid()))throw new AccessDeniedException("无权读取营业执照");return file;}
}
